"""Spec tests: compile + run programs, capture output exactly."""

import io
from contextlib import redirect_stdout

import pytest

from vm import compile_source, run, VmError, disasm, assemble


def compile_and_run(src):
    """Compile src, execute it, return the list of printed values.

    Also prints the values to stdout so callers can assert on captured stdout.
    """
    out = run(compile_source(src))
    print("\n".join(str(v) for v in out))
    return out


def test_while_accumulates_sum_prints_45(capsys):
    src = """
    x = 0;
    sum = 0;
    while (x < 10) {
        x = x + 1;
        sum = sum + x;
    }
    print(sum);
    """
    out = compile_and_run(src)
    captured = capsys.readouterr().out
    assert out == [45]
    assert captured == "45\n"


def test_nested_if_else(capsys):
    src = """
    x = 7;
    y = 3;
    if (x > y) {
        if (x == 7) {
            print(100);
        } else {
            print(101);
        }
    } else {
        if (y == 3) {
            print(200);
        } else {
            print(201);
        }
    }
    print(x * y);
    """
    out = compile_and_run(src)
    captured = capsys.readouterr().out
    assert out == [100, 21]
    assert captured == "100\n21\n"


def test_else_branch_taken(capsys):
    src = """
    x = 2;
    if (x > 5) {
        print(1);
    } else {
        print(2);
    }
    """
    out = compile_and_run(src)
    captured = capsys.readouterr().out
    assert out == [2]
    assert captured == "2\n"


def test_iterative_fibonacci_prints_6765(capsys):
    src = """
    n = 20;
    a = 0;
    b = 1;
    i = 0;
    while (i < n) {
        t = a + b;
        a = b;
        b = t;
        i = i + 1;
    }
    print(a);
    """
    out = compile_and_run(src)
    captured = capsys.readouterr().out
    assert out == [6765]
    assert captured == "6765\n"


def test_arithmetic_precedence_and_division(capsys):
    src = """
    print(2 + 3 * 4);
    print((2 + 3) * 4);
    print(17 / 5);
    print(-7 / 2);
    print(10 - 3 - 2);
    """
    out = compile_and_run(src)
    captured = capsys.readouterr().out
    assert out == [14, 20, 3, -3, 5]
    assert captured == "14\n20\n3\n-3\n5\n"


def test_division_by_zero_raises_vm_error_with_ip():
    from vm.compiler import OP_DIV

    src = """
    x = 0;
    print(1 / x);
    """
    program = compile_source(src)
    with pytest.raises(VmError) as excinfo:
        run(program)
    error = excinfo.value
    assert "division by zero" in str(error)
    # the failing instruction must be the DIV itself
    assert program["code"][error.ip] == OP_DIV


def test_stack_underflow_raises_vm_error_with_ip():
    program = {"code": [3, 4], "consts": [], "nlocals": 0}  # ADD with empty stack
    with pytest.raises(VmError) as excinfo:
        run(program)
    assert "stack underflow" in str(excinfo.value)
    assert excinfo.value.ip == 0


def test_compile_error_on_read_before_assign():
    from vm.compiler import CompileError

    with pytest.raises(CompileError):
        compile_source("print(y);")


def test_disasm_assemble_round_trip():
    src = """
    n = 20;
    a = 0;
    b = 1;
    i = 0;
    while (i < n) {
        t = a + b;
        a = b;
        b = t;
        i = i + 1;
    }
    if (a == 6765) {
        print(a);
    } else {
        print(0);
    }
    """
    original = compile_source(src)
    text = disasm(original)
    rebuilt = assemble(text)
    assert rebuilt == original

    # and the rebuilt program still runs correctly
    assert run(rebuilt) == [6765]


def test_assemble_accepts_hand_written_labels():
    # count down from 3 to 0 using a labeled loop
    asm_text = """
    .const 0 3
    .const 1 1
    .nlocals 1
    0: PUSH 0
    2: STORE 0
    loop:
    4: LOAD 0
    6: JZ end
    8: LOAD 0
    10: PUSH 1
    12: SUB
    13: STORE 0
    15: JMP loop
    end:
    17: PRINT
    18: HALT
    """
    program = assemble(asm_text)
    assert run(program) == [0]

